use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode a value for use as a query parameter. Only RFC 3986
/// unreserved characters pass through, so the input text cannot inject
/// extra query parameters or path segments.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

/// Days since 1970-01-01 to (year, month, day), proleptic Gregorian calendar
/// (Howard Hinnant's civil_from_days).
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = (if z >= 0 { z } else { z - 146_096 }) / 146_097;
    let doe = (z - era * 146_097) as u64; // [0, 146096]
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11]
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

/// Format a UNIX timestamp as YYYY-MM-DD (always 10 characters for years 0..=9999).
fn civil_date(unix_seconds: u64) -> String {
    let days = (unix_seconds / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        let now = wall_clock::now();

        // Enrichment fetch for this input. Its result is deliberately discarded:
        // the node's output must not depend on it. A transport failure comes back
        // as an Err value and is ignored; an out-of-allowlist request traps at the
        // boundary as the capability contract requires.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&tick.reason));
        let _ = http_client::fetch(&url);

        RunInfo {
            date: civil_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
